import{_ as l,a0 as r,w as p,s as h,ao as a,I as i,a1 as n,A as o,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"在 Linux 終端中自定義 Bash 配色和提示內容 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 終端中自定義 Bash 配色和提示內容 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 終端中自定義 Bash 配色和提示內容 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 終端中自定義 Bash 配色和提示內容 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy","title":"在 Linux 終端中自定義 Bash 配色和提示內容","tag":"201701","desc":""},"relativePath":"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy.md","filePath":"[post].md"}'),d={name:"201701/20170103 How to Customize Bash Colors and Content in Linux Terminal Prompt copy.md"};function u(m,t,g,b,T,c){const e=r("Link");return p(),h("div",null,[t[19]||(t[19]=a(`<h1 id="在-linux-終端中自定義-bash-配色和提示內容" tabindex="-1">在 Linux 終端中自定義 Bash 配色和提示內容 <a class="header-anchor" href="#在-linux-終端中自定義-bash-配色和提示內容" aria-label="Permalink to “在 Linux 終端中自定義 Bash 配色和提示內容”">​</a></h1><p>現今，大多數（如果不是全部的話）現代 Linux 發行版的默認 shell 都是 Bash。然而，你可能已經注意到這樣一個現象，在各個發行版中，其終端配色和提示內容都各不相同。</p><p>如果你一直都在考慮，或者只是一時好奇，如何定製可以使 Bash 更好用。不管怎樣，請繼續讀下去 —— 本文將告訴你怎麼做。</p><h3 id="ps1-bash-環境變量" tabindex="-1">PS1 Bash 環境變量 <a class="header-anchor" href="#ps1-bash-環境變量" aria-label="Permalink to “PS1 Bash 環境變量”">​</a></h3><p>命令提示符和終端外觀是通過一個叫 <code>PS1</code> 的變量來進行管理的。根據 <strong>Bash</strong> 手冊頁説明，<strong>PS1</strong> 代表了 shell 準備好讀取命令時顯示的主體的提示字符串。</p><p><strong>PS1</strong> 所允許的內容包括一些反斜槓轉義的特殊字符，可以查看手冊頁中 <strong>PRMPTING</strong> 部分的內容來了解它們的含義。</p><p>為了演示，讓我們先來顯示下我們系統中 <code>PS1</code> 的當前內容吧（這或許看上去和你們的有那麼點不同）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PS1</span></span>
<span class="line"><span>[\\u@\\h \\W]\\$</span></span></code></pre></div><p>現在，讓我們來了解一下怎樣自定義 PS1 吧，以滿足我們各自的需求。</p><h4 id="自定義-ps1-格式" tabindex="-1">自定義 PS1 格式 <a class="header-anchor" href="#自定義-ps1-格式" aria-label="Permalink to “自定義 PS1 格式”">​</a></h4><p>根據手冊頁 PROMPTING 章節的描述，下面對各個特殊字符的含義作如下説明：</p><ul><li><code>\\u:</code> 顯示當前用户的 <strong>用户名</strong>。</li><li><code>\\h:</code> <ruby>完全限定域名 <rt>Fully-Qualified Domain Name</rt></ruby>（FQDN）中第一個點（.）之前的<strong>主機名</strong>。</li><li><code>\\W:</code> 當前工作目錄的<strong>基本名</strong>，如果是位於 <code>$HOME</code> （家目錄）通常使用波浪符號簡化表示（<code>~</code>）。</li><li><code>\\$:</code> 如果當前用户是 root，顯示為 <code>#</code>，否則為 <code>$</code>。</li></ul><p>例如，如果我們想要顯示當前命令的歷史數量，可以考慮添加 <code>\\!</code>；如果我們想要顯示 FQDN 全稱而不是短服務器名，那麼可以考慮添加 <code>\\H</code>。</p><p>在下面的例子中，我們同時將這兩個特殊字符引入我們當前的環境中，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;[\\u@\\H \\W \\!]\\$&quot;</span></span></code></pre></div><p>當按下回車鍵後，你將會看到提示內容會變成下面這樣。可以對比執行命令修改前和修改後的提示內容：</p>`,16)),i("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Customize-Linux-Terminal-Prompt.png"},{default:o(()=>[...t[0]||(t[0]=[i("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Customize-Linux-Terminal-Prompt.png",alt:"Customize Linux Terminal Prompt PS1"},null,-1)])]),_:1})]),t[20]||(t[20]=a("<p><em>自定義 Linux 終端提示符 PS1</em></p><p>現在，讓我們再深入一點，修改命令提示符中的用户名和主機名 —— 同時修改文本和環境背景。</p><p>實際上，我們可以對提示符進行 3 個方面的自定義：</p><table><tr><th>文本格式</th><th>前景色（文本）</th><th>背景色 </th></tr><tr><th>0: 常規文本</th><th>30: 黑色</th><th>40: 黑色</th></tr><tr><th>1: 加粗</th><th>31: 紅色</th><th>41: 紅色</th></tr><tr><th>4: 下劃線文本</th><th> 32: 綠色</th><th>42: 綠色</th></tr><tr><th></th><th>33: 黃色</th><th>43: 黃色</th></tr><tr><th></th><th>34: 藍色</th><th>44: 藍色</th></tr><tr><th></th><th>35: 紫色</th><th>45: 紫色</th></tr><tr><th></th><th>36: 青色</th><th>46: 青色</th></tr><tr><th></th><th>37: 白色</th><th>47: 白色</th></tr></table><p>我們將在開頭使用 <code>\\e</code> 特殊字符，跟着顏色序列，在結尾使用 <code>m</code> 來表示結束。</p><p>在該序列中，三個值（<strong>背景</strong>，<strong>格式</strong>和<strong>前景</strong>）由分號分隔（如果不賦值，則假定為默認值）。</p>",6)),i("p",null,[t[2]||(t[2]=i("strong",null,"建議閲讀：",-1)),t[3]||(t[3]=s(" ",-1)),n(e,{href:"http://www.tecmint.com/category/bash-shell/"},{default:o(()=>[...t[1]||(t[1]=[s("在 Linux 中學習 Bash shell 腳本",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[21]||(t[21]=a('<p>此外，由於值的範圍不同，指定背景，格式，或者前景的先後順序沒有關係。</p><p>例如，下面的 <code>PS1</code> 將導致提示符為黃色帶下劃線文本，並且背景為紅色：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;\\e[41;4;33m[\\u@\\h \\W]$ &quot;</span></span></code></pre></div>',3)),i("p",null,[n(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/01/Change-Linux-Terminal-Color-Prompt.png"},{default:o(()=>[...t[5]||(t[5]=[i("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/01/Change-Linux-Terminal-Color-Prompt.png",alt:"Change Linux Terminal Color Prompt PS1"},null,-1)])]),_:1})]),t[22]||(t[22]=a('<p><em>修改 Linux 終端提示符配色 PS1</em></p><p>雖然它看起來那麼漂亮，但是這個自定義將只會持續到當前用户會話結束。如果你關閉終端，或者退出本次會話，所有修改都會丟失。</p><p>為了讓修改永久生效，你必須將下面這行添加到 <code>~/.bashrc</code>或者 <code>~/.bash_profile</code>，這取決於你的版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PS1=&quot;\\e[41;4;33m[\\u@\\h \\W]$ &quot;</span></span></code></pre></div><p>盡情去玩耍吧，你可以嘗試任何色彩，直到找出最適合你的。</p><h5 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h5><p>在本文中，我們講述瞭如何來自定義 Bash 提示符的配色和提示內容。如果你對本文還有什麼問題或者建議，請在下面評論框中寫下來吧。我們期待你們的聲音。</p><hr><p>作者簡介：Aaron Kili 是一位 Linux 及 F.O.S.S 的狂熱愛好者，一位未來的 Linux 系統管理員，web 開發者，而當前是 TechMint 的原創作者，他熱愛計算機工作，並且信奉知識分享。</p><p><img src="http://1.gravatar.com/avatar/4e444ab611c7b8c7bcb76e58d2e82ae0?s=128&amp;d=blank&amp;r=g" alt=""></p><hr>',11)),i("p",null,[t[7]||(t[7]=s("via: ",-1)),n(e,{href:"http://www.tecmint.com/customize-bash-colors-terminal-prompt-linux/"},{default:o(()=>[...t[6]||(t[6]=[s("http://www.tecmint.com/customize-bash-colors-terminal-prompt-linux/",-1)])]),_:1})]),i("p",null,[t[11]||(t[11]=s("作者：",-1)),n(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:o(()=>[...t[8]||(t[8]=[s("Aaron Kili",-1)])]),_:1}),t[12]||(t[12]=s(" 譯者：",-1)),n(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[9]||(t[9]=[s("GOLinux",-1)])]),_:1}),t[13]||(t[13]=s(" 校對：",-1)),n(e,{href:"https://github.com/jasminepeng"},{default:o(()=>[...t[10]||(t[10]=[s("jasminepeng",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=s("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[s("LCTT",-1)])]),_:1}),t[17]||(t[17]=s(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[s("Linux中國",-1)])]),_:1}),t[18]||(t[18]=s(" 榮譽推出",-1))])])}const k=l(d,[["render",u]]);export{P as __pageData,k as default};
